<script setup lang="ts">
import { ref, watch } from 'vue'
import { api } from '../api'
import BatchQRCode from './BatchQRCode.vue'
import { externalTraceError } from '../product-management'
import { productCSVTemplate, type ImportPreview, type ManagedBatch } from '../product-management'
import type { Product } from '../types'
const props=defineProps<{mode:string;productId:string;selectedProduct?:Product}>(),emit=defineEmits<{saved:[]}>()
const content=ref(''),preview=ref<ImportPreview|null>(null),busy=ref(false),error=ref(''),success=ref(''),fileName=ref('')
const batches=ref<ManagedBatch[]>([]),total=ref(0),offset=ref(0),keyword=ref(''),status=ref(''),editing=ref<ManagedBatch|null>(null),productKeyword=ref(''),choices=ref<Product[]>([])
const qrBatch=ref<ManagedBatch|null>(null)
let request=0
async function load(next=0){const id=++request;busy.value=true;error.value='';try{const result=await api<{items:ManagedBatch[];total:number}>('admin.batch.list',{productId:props.productId,keyword:keyword.value,status:status.value,offset:next,limit:20});if(id!==request)return;batches.value=result.items;total.value=result.total;offset.value=next}catch(e){if(id===request)error.value=(e as Error).message}finally{if(id===request)busy.value=false}}
watch(()=>[props.mode,props.productId],()=>{if(props.mode==='batches')load()},{immediate:true})
function template(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([productCSVTemplate],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='商品导入模板.csv';a.click();URL.revokeObjectURL(url)}
async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];preview.value=null;content.value='';success.value='';error.value='';if(!file)return;if(file.size>1024*1024){error.value='文件不能超过 1MB';return}fileName.value=file.name;busy.value=true;try{content.value=await file.text();preview.value=await api<ImportPreview>('admin.product.import',{content:content.value,preview:true})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function confirmImport(){if(!preview.value||preview.value.errors.length||!content.value||busy.value)return;busy.value=true;error.value='';try{const result=await api<{created:number;skus:number}>('admin.product.import',{content:content.value,preview:false});success.value=`已创建 ${result.created} 款草稿、${result.skus} 个规格`;content.value='';preview.value=null;emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function lookup(){try{const items=(await api<{items:Product[]}>('admin.product.search',{keyword:productKeyword.value,limit:20})).items;choices.value=props.selectedProduct?[props.selectedProduct,...items.filter(p=>p.id!==props.selectedProduct?.id)]:items}catch(e){error.value=(e as Error).message}}
function edit(b?:ManagedBatch){editing.value=b?JSON.parse(JSON.stringify(b)):{id:'',productId:props.productId,number:'',orchard:'',harvestedAt:'',packedAt:'',expiresAt:'',note:'',status:'ACTIVE',version:0};error.value='';if(!b)lookup()}
async function saveBatch(){if(busy.value||!editing.value)return;error.value=externalTraceError(editing.value.externalTrace);if(error.value)return;busy.value=true;error.value='';try{await api('admin.batch.save',{batch:editing.value});editing.value=null;await load(offset.value)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
 <section v-if="mode==='import'" class="panel tools-panel">
  <h3>批量导入商品</h3><p>上传 UTF-8 CSV，每行一个规格；同一商品使用相同分组。最多 500 个规格、1MB。导入统一创建草稿，检查后再上架。</p>
  <div class="row-actions"><button class="button secondary" @click="template">下载 CSV 模板</button><label class="button secondary">选择 CSV 文件<input type="file" accept=".csv,text/csv" :disabled="busy" @change="readFile"/></label></div>
  <p v-if="busy" aria-live="polite">处理中…</p><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="success" role="status">{{success}}</p>
  <div v-if="preview"><p>{{fileName}}：{{preview.rows}} 行，{{preview.products.length}} 款商品</p><ul v-if="preview.errors.length" class="form-error"><li v-for="e in preview.errors" :key="e">{{e}}</li></ul>
  <div class="table-panel"><table><thead><tr><th>商品</th><th>规格</th><th>售价</th><th>库存</th></tr></thead><tbody><template v-for="(p,index) in preview.products" :key="index"><tr v-for="(s,i) in p.skus" :key="i"><td>{{p.name}}</td><td>{{s.name}}</td><td>¥{{(s.price/100).toFixed(2)}}</td><td>{{s.stock}}</td></tr></template></tbody></table></div>
  <button v-permission="['product.write','inventory.write']" class="button primary" :disabled="busy||!!preview.errors.length" @click="confirmImport">确认创建 {{preview.products.length}} 款草稿</button></div>
 </section>
 <section v-if="mode==='batches'" class="panel tools-panel">
  <div class="toolbar"><div><h3>批次管理</h3><p>登记果园、采收、包装和有效期；归档后保留历史资料。发货前在订单中登记实际批次及数量；溯源码可供买家独立查询。批次档案不改变可售库存。</p></div><button v-permission="'product.write'" class="button primary" @click="edit()">新增批次</button></div>
  <form class="row-actions" @submit.prevent="load()"><input v-model.trim="keyword" placeholder="搜索批次号 / 果园" maxlength="60"/><select v-model="status"><option value="">全部状态</option><option value="ACTIVE">使用中</option><option value="ARCHIVED">已归档</option></select><button class="button secondary" :disabled="busy">查询</button></form>
  <p v-if="error&&!editing" class="form-error" role="alert">{{error}}</p><p v-if="busy&&!editing">加载中…</p>
  <div class="table-panel"><table><thead><tr><th>批次 / 商品编号</th><th>果园</th><th>采收 / 包装</th><th>有效期</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="b in batches" :key="b.id"><td><strong>{{b.number}}</strong><small class="block">{{b.productId}}</small><small class="block">溯源码：{{b.code||b.id}}</small></td><td>{{b.orchard}}</td><td>{{b.harvestedAt||'待采收'}}<small class="block">{{b.packedAt||'待包装'}}</small></td><td>{{b.expiresAt||'未设置'}}</td><td>{{b.status==='ACTIVE'?'使用中':'已归档'}}</td><td><button v-permission="'product.write'" class="text-button" @click="edit(b)">编辑 / 归档</button><button class="text-button" @click="qrBatch=JSON.parse(JSON.stringify(b))">生成二维码</button><small v-if="b.externalTrace" class="block">外部平台：{{b.externalTrace.platform}}</small></td></tr><tr v-if="!batches.length"><td colspan="6">暂无批次资料</td></tr></tbody></table></div>
  <div class="row-actions"><span>共 {{total}} 条</span><button class="button secondary" :disabled="busy||offset===0" @click="load(offset-20)">上一页</button><span>第 {{Math.floor(offset/20)+1}} 页</span><button class="button secondary" :disabled="busy||offset+20>=total" @click="load(offset+20)">下一页</button></div>
 </section>
 <div v-if="editing" class="modal-backdrop"><form class="drawer" @submit.prevent="saveBatch"><div class="drawer-head"><h2>{{editing.id?'编辑批次':'新增批次'}}</h2><button class="close" type="button" :disabled="busy" @click="editing=null">×</button></div><div class="drawer-body form-grid">
  <template v-if="!editing.id"><label class="full">搜索关联商品<div class="row-actions"><input v-model.trim="productKeyword" maxlength="60" placeholder="商品名称"/><button type="button" class="button secondary" @click="lookup">搜索商品</button></div></label><label class="full">关联商品<select v-model="editing.productId" required><option value="">请选择</option><option v-for="p in choices" :key="p.id" :value="p.id">{{p.name}}（{{p.id}}）</option></select></label></template><p v-else class="full">商品编号：{{editing.productId}}</p>
  <label>批次号<input v-model.trim="editing.number" required maxlength="120"/></label><label>果园 / 地块<input v-model.trim="editing.orchard" required maxlength="200"/></label><label>采收日期<input v-model="editing.harvestedAt" type="date"/></label><label>包装日期<input v-model="editing.packedAt" type="date" :min="editing.harvestedAt||undefined"/></label><label>有效期至<input v-model="editing.expiresAt" type="date" :min="editing.packedAt||editing.harvestedAt||undefined"/></label><label>状态<select v-model="editing.status" aria-label="批次状态"><option value="ACTIVE">使用中</option><option value="ARCHIVED">归档</option></select></label><div class="full"><div class="sku-head"><strong>外部溯源平台</strong><button v-if="!editing.externalTrace" type="button" class="text-button" @click="editing.externalTrace={platform:'',url:'',code:''}">＋ 关联平台</button></div><div v-if="editing.externalTrace" class="form-grid">
  <label>平台名称<input v-model.trim="editing.externalTrace.platform" required maxlength="80"/></label><label>平台溯源编码<input v-model.trim="editing.externalTrace.code" maxlength="120"/></label><label class="full">该批次溯源链接<input v-model.trim="editing.externalTrace.url" type="url" required maxlength="1000" placeholder="https://平台域名/该批次溯源页面"/><small>公开链接会展示给买家，请使用该批次的查询地址。</small></label><button type="button" class="text-button" @click="delete editing.externalTrace">移除外部平台</button></div></div><label class="full">备注<textarea v-model.trim="editing.note" rows="3" maxlength="1000"/></label><p v-if="error" class="form-error full" role="alert">{{error}}</p>
 </div><div class="drawer-foot"><button type="button" class="button secondary" :disabled="busy" @click="editing=null">取消</button><button v-permission="'product.write'" class="button primary" :disabled="busy">{{busy?'保存中…':'保存批次'}}</button></div></form></div>
<BatchQRCode v-if="qrBatch" :batch="qrBatch" @close="qrBatch=null"/>
</template>
<style scoped>
.tools-panel{padding:24px;margin-bottom:24px}.tools-panel p{margin:12px 0;line-height:1.7}.tools-panel .row-actions{margin:16px 0;flex-wrap:wrap}.tools-panel input,.tools-panel select{padding:10px;border:1px solid var(--border);border-radius:8px}.table-panel{overflow:auto;max-height:480px;margin:20px 0}input[type=file]{max-width:240px}table{min-width:680px}
</style>
